```go
func (m *Model) joinPanes() string {
	listHeight, detailHeight := m.layout.paneHeights()
	listPane := m.frame(m.views[m.active].View(), m.layout.ListWidth, listHeight, false)
	if m.detail == nil || m.layout.DetailWidth <= 0 {
		return listPane
	}

	detailPane := m.frame(m.detail.View(), m.layout.DetailWidth, detailHeight, false)
	if m.layout.Stacked {
		return lipgloss.JoinVertical(lipgloss.Left, listPane, detailPane)
	}

	return lipgloss.JoinHorizontal(lipgloss.Top, listPane, m.separator(), detailPane)
}

// frame draws pane's border, or returns pane untouched when Compute decided
// the terminal could not afford one. width and height are the pane's content
// box, already net of the frame (Task 1.1's deductBorders and paneHeights) —
// lipgloss draws the border outside the box Width and Height set, so passing
// the outer size here would overflow by exactly the frame.
func (m *Model) frame(pane string, width, height int, focused bool) string {
	if !m.layout.Bordered {
		return pane
	}

	return m.theme.Frame(focused).Width(width).Height(height).Render(pane)
}

// separator is the blank gutter column between side-by-side panes. A framed
// layout has none — the two adjacent borders already separate the panes, and
// keeping the gutter as well would leave a visible three-cell channel between
// them. Task 1.1's Layout.separatorWidth makes the same decision for the
// geometry; this is its rendering half.
func (m *Model) separator() string {
	if m.layout.Bordered {
		return ""
	}

	return gutter(m.layout.BodyHeight)
}
```

